mockup.css:
.mock-section-full-bleed-split { display: grid; grid-template-columns: 1fr 1fr; }
.mock-section-full-bleed-split .copy { background: #1d2a33; color: #eef2f4; font-family: var(--f-sans);
  display: flex; flex-direction: column; justify-content: center; gap: 2.2cqw; padding: 0 7cqw; }
.mock-section-full-bleed-split .copy h4 { margin: 0; font-family: var(--f-serif); font-size: 4.8cqw;
  line-height: 1.05; letter-spacing: -.02em; }
.mock-section-full-bleed-split .copy p { margin: 0; font-size: 1.55cqw; line-height: 1.55; opacity: .75; max-width: 30ch; }
.mock-section-full-bleed-split .copy .cta { font-size: 1.25cqw; letter-spacing: .14em; text-transform: uppercase;
  border-bottom: 1px solid; padding-bottom: .6cqw; align-self: flex-start; }
